const checkedAt = new Date().toISOString();
const inputItems = $input.all();
if (!inputItems.length) {
  return [{ json: { recordKind: 'rssParseMeta', fetchOk: false, classification: 'SOURCE_API_BLOCKED', error: 'No response reached the fetch node', httpStatus: 0, itemCount: 0, checkedAt } }];
}
const raw = inputItems[0].json || {};
const status = Number(raw.statusCode || 0);
const bodyText = String(raw.body !== undefined ? raw.body : (raw.data !== undefined ? raw.data : ''));

if (!status || status < 200 || status >= 300 || !bodyText) {
  return [{ json: { recordKind: 'rssParseMeta', fetchOk: false, classification: 'SOURCE_API_BLOCKED', httpStatus: status || 0, error: 'Vigicrues RSS request failed or returned an empty body.', itemCount: 0, checkedAt } }];
}

function decodeEntities(value) {
  return String(value || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_m, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_m, code) => String.fromCharCode(parseInt(code, 16)));
}
function stripHtml(value) {
  return decodeEntities(value)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function firstTag(block, tag) {
  const m = block.match(new RegExp('<' + tag + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + tag + '>', 'i'));
  return m ? decodeEntities(m[1]).trim() : '';
}

const items = [...bodyText.matchAll(/<item\b[^>]*>([\s\S]*?)<\/item>/gi)].map((m) => {
  const block = m[1];
  return {
    title: stripHtml(firstTag(block, 'title')),
    link: stripHtml(firstTag(block, 'link')),
    description: stripHtml(firstTag(block, 'description')),
    pubDate: stripHtml(firstTag(block, 'pubDate')),
    guid: stripHtml(firstTag(block, 'guid')),
  };
});

const meta = { recordKind: 'rssParseMeta', fetchOk: true, httpStatus: status, itemCount: items.length, checkedAt };
return [
  { json: meta },
  ...items.map((item) => ({ json: { recordKind: 'rssItem', ...item, checkedAt } })),
];

const checkedAt = new Date().toISOString();
const config = $items('Set Connector Config')[0].json;
const mappingItems = $items('Load / Embed Verified Station Mapping');
const stations = (mappingItems[0] && mappingItems[0].json.stations) || [];

const allInputs = $input.all().map((i) => i.json || {});
const meta = allInputs.find((i) => i.recordKind === 'rssParseMeta') || { fetchOk: false, itemCount: 0, httpStatus: 0 };
const rssItems = allInputs.filter((i) => i.recordKind === 'rssItem');

const vigilanceLevels = new Set(['vert', 'jaune', 'orange', 'rouge']);
const labelFr = { vert: 'Vert', jaune: 'Jaune', orange: 'Orange', rouge: 'Rouge' };
const labelEn = { vert: 'Green', jaune: 'Yellow', orange: 'Orange', rouge: 'Red' };
const colorFor = { vert: 'green', jaune: 'yellow', orange: 'orange', rouge: 'red' };

function normalize(value) {
  return String(value || '')
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function extractVigilanceLevel(text) {
  const n = normalize(text);
  if (/ pas de vigilance particuliere /.test(n)) return null;
  const explicit = n.match(/ vigilances+(verte?|jaune|orange|rouge) /);
  const loose = explicit || n.match(/ (vert|verte|jaune|orange|rouge) /);
  if (!loose) return null;
  const level = loose[1] === 'verte' ? 'vert' : loose[1];
  return vigilanceLevels.has(level) ? level : null;
}

const preparedStations = stations.map((s) => ({
  ...s,
  normalizedName: normalize(s.stationName),
  normalizedRiver: normalize(s.river),
  normalizedCode: normalize(s.stationCode),
}));

function matchStation(item) {
  const haystack = normalize([item.title, item.description, item.link, item.guid].filter(Boolean).join(' '));
  const scored = preparedStations.map((station) => {
    let score = 0;
    const reasons = [];
    if (station.stationCode && haystack.includes(normalize(station.stationCode))) { score += 100; reasons.push('station_code'); }
    if (station.normalizedName && haystack.includes(station.normalizedName)) { score += 80; reasons.push('station_name'); }
    const placeName = station.normalizedName.replace(new RegExp('^' + station.normalizedRiver + '\s+a\s+'), '');
    if (placeName && placeName.length >= 4 && haystack.includes(placeName)) { score += 45; reasons.push('place_name'); }
    const placeTokens = placeName.split(/\s+/).filter((t) => t.length >= 5 && t !== 'corridor');
    if (station.normalizedRiver && haystack.includes(station.normalizedRiver) && placeTokens.some((t) => haystack.includes(t))) { score += 25; reasons.push('river_place_token'); }
    const deptMatch = (station.departments || []).some((d) => {
      const padded = String(d).padStart(2, '0');
      return new RegExp('\b(' + d + '|' + padded + ')\b').test(haystack);
    });
    if (station.normalizedRiver && haystack.includes(station.normalizedRiver) && deptMatch) { score += 35; reasons.push('river_department'); }
    return { station, score, reasons };
  }).filter((e) => e.score > 0);
  scored.sort((a, b) => b.score - a.score);
  return scored[0] || null;
}

function externalIdFor(station, level, item) {
  const stable = item.guid || item.link || item.title || (station.stationCode + ':' + level);
  const s = station.stationCode + ':' + level + ':' + stable;
  let hash = 0;
  for (let i = 0; i < s.length; i++) { hash = (Math.imul(31, hash) + s.charCodeAt(i)) | 0; }
  return 'vigicrues-' + station.stationCode + '-' + level + '-' + (hash >>> 0).toString(16);
}

const floodWarningRecords = [];
const ignoredItems = [];
let latestSourceUpdatedAt = null;

for (const item of rssItems) {
  if (!Number.isNaN(Date.parse(item.pubDate || ''))) {
    const normalizedPubDate = new Date(item.pubDate).toISOString();
    if (!latestSourceUpdatedAt || normalizedPubDate > latestSourceUpdatedAt) latestSourceUpdatedAt = normalizedPubDate;
  }
}

if (meta.fetchOk) {
  for (const item of rssItems) {
    const text = [item.title, item.description].filter(Boolean).join(' ');
    const level = extractVigilanceLevel(text);
    if (!level) { ignoredItems.push({ title: item.title, reason: 'no_vigilance_level' }); continue; }
    if (level === 'vert') { ignoredItems.push({ title: item.title, reason: 'green_vigilance' }); continue; }

    const match = matchStation(item);
    if (!match) { ignoredItems.push({ title: item.title, vigilanceLevel: level, reason: 'no_mapped_station_match' }); continue; }

    const station = match.station;
    const confidence = match.score >= 80 ? 'high' : match.score >= 40 ? 'medium' : 'low';
    const rideDays = Array.isArray(station.rideDays) ? station.rideDays : [];
    const hasRideDays = rideDays.length > 0;
    const reviewState = (confidence !== 'low' && hasRideDays) ? 'auto_publish_candidate' : 'manual_review_required';
    const url = item.link || station.lookupUrl || 'https://www.vigicrues.gouv.fr/';
    const updatedAt = Number.isNaN(Date.parse(item.pubDate)) ? checkedAt : new Date(item.pubDate).toISOString();

    for (const rideDayId of (hasRideDays ? rideDays : [null])) {
      const rdMatch = String(rideDayId || '').match(/^RD0?([1-9])$/);
      const rideDay = rdMatch ? Number(rdMatch[1]) : null;
      floodWarningRecords.push({
        recordKind: 'officialFloodWarning',
        externalId: externalIdFor(station, level, item) + (rideDayId ? ('-' + rideDayId) : ''),
        sourceId: 'vigicrues',
        sourceType: 'vigicrues',
        category: 'official_flood_warning',
        semanticStatus: 'river_flood_vigilance',
        officialWarningLevel: level,
        officialWarningColor: colorFor[level],
        officialWarningLabelFr: labelFr[level],
        officialWarningLabelEn: labelEn[level],
        routeImpactStatus: 'not_indicated',
        routeClosureConfirmed: false,
        towpathClosureConfirmed: false,
        publicAccessClosureConfirmed: false,
        detourConfirmed: false,
        status: 'warning',
        title: 'Official flood warning in place (vigilance ' + level + ') - no route impact indicated',
        nearestPlace: station.stationName,
        stationCode: station.stationCode,
        stationName: station.stationName,
        river: station.river,
        departmentCode: String((station.departments || [])[0] || ''),
        departmentName: String((station.departments || [])[0] || ''),
        rideDay,
        rideDays,
        distanceFromRouteKm: Number(station.distanceFromRouteKm),
        nearestRouteKm: Number(station.nearestRouteKm),
        nearestRouteMp: Number(station.nearestRouteMp),
        stationMappingVerified: station.verified === true,
        stationMatchConfidence: confidence,
        reviewState,
        routeInfluenceConfirmed: false,
        routeSpecific: false,
        departmentalGeneral: false,
        routeCorridorRelevant: true,
        relevanceScope: 'route_corridor_station_match',
        startTime: updatedAt,
        expectedEndTime: null,
        checkedAt,
        sourceUrl: url,
        summary: 'Vigicrues reports ' + labelEn[level].toLowerCase() + ' flood vigilance for ' + station.river + ' near ' + station.stationName + '. Official flood warning in place - no route impact indicated.',
        statusTitle: 'Official flood warning in place (vigilance ' + level + ') - no route impact indicated',
        statusExplanation: 'Vigicrues reports official ' + labelEn[level].toLowerCase() + ' flood vigilance near ' + station.stationName + '; no official route or towpath closure is indicated at this time.',
        statusSource: { name: 'Vigicrues', url, official: true, checkedAt, sourceLanguage: 'fr', translationMethod: 'condensed_official_source' },
        whyItMatters: 'An official river flood vigilance is in effect near the route corridor; this does not by itself mean the route or towpath is closed.',
        recommendedAction: 'Check Vigicrues and official local route notices before riding near the affected watercourse.',
        suggestedDetour: null,
        detourImpact: null,
        raw: { title: item.title, description: item.description, matchReasons: match.reasons },
      });
    }
  }
}

const outMeta = {
  recordKind: 'normalizeMeta',
  fetchOk: meta.fetchOk,
  httpStatus: meta.httpStatus || 0,
  itemCount: meta.itemCount || 0,
  floodWarningRecordCount: floodWarningRecords.length,
  ignoredCount: ignoredItems.length,
  latestSourceUpdatedAt,
};

return [
  { json: outMeta },
  ...floodWarningRecords.map((r) => ({ json: r })),
  ...ignoredItems.map((i) => ({ json: { recordKind: 'ignoredItem', ...i } })),
];

const checkedAt = new Date().toISOString();
const config = $items('Set Connector Config')[0].json;
const normalizeItems = $items('Extract And Normalize Flood Warning Records').map((i) => i.json);
const meta = normalizeItems.find((i) => i.recordKind === 'normalizeMeta') || { fetchOk: false, httpStatus: 0, itemCount: 0, floodWarningRecordCount: 0, ignoredCount: 0, latestSourceUpdatedAt: null };
const ignored = normalizeItems.filter((i) => i.recordKind === 'ignoredItem').map((i) => ({ title: i.title, reason: i.reason, vigilanceLevel: i.vigilanceLevel || null }));

const staleAfterMinutes = Number(config.staleAfterMinutes);
const sourceUpdatedAt = meta.latestSourceUpdatedAt || null;
const stale = Boolean(sourceUpdatedAt) && ((Date.parse(checkedAt) - Date.parse(sourceUpdatedAt)) > (staleAfterMinutes * 60 * 1000));

let status;
const errors = [];
const warnings = [];
if (!meta.fetchOk) {
  status = 'source_api_blocked';
  errors.push('Vigicrues RSS request failed (httpStatus=' + (meta.httpStatus || 0) + ').');
} else if (stale) {
  status = 'stale';
  warnings.push('Latest Vigicrues source update is older than the configured stale threshold of ' + staleAfterMinutes + ' minutes.');
} else {
  status = 'ok';
}

return [{
  json: {
    recordKind: 'sourceHealth',
    sourceId: 'vigicrues',
    sourceName: 'Vigicrues',
    status,
    fetchedAt: checkedAt,
    sourceUpdatedAt,
    stale,
    staleAfterMinutes,
    httpStatus: meta.httpStatus || 0,
    itemCount: meta.itemCount || 0,
    officialWarningCount: meta.floodWarningRecordCount || 0,
    ignoredCount: meta.ignoredCount || 0,
    recordCount: meta.floodWarningRecordCount || 0,
    ignored,
    errors,
    warnings,
  }
}];

const config = $items('Set Connector Config')[0].json;
const floodWarnings = $items('Extract And Normalize Flood Warning Records').map((i) => i.json).filter((i) => i.recordKind === 'officialFloodWarning');

const events = [];
const reviewQueue = [];
for (const w of floodWarnings) {
  const candidate = {
    eventType: 'flood_hazard',
    sourceType: 'vigicrues',
    sourceId: 'vigicrues',
    sourceName: 'Vigicrues',
    officialWarningLevel: w.officialWarningLevel,
    officialWarningColor: w.officialWarningColor,
    routeImpactStatus: w.routeImpactStatus,
    routeClosureConfirmed: false,
    towpathClosureConfirmed: false,
    reviewState: w.reviewState,
    stationMappingVerified: w.stationMappingVerified,
    matchConfidence: w.stationMatchConfidence,
    title: 'Official flood warning in place - no route impact indicated: ' + w.stationName,
    summary: w.summary + ' Route closure not confirmed.',
    rideDay: w.rideDay,
    rideDays: w.rideDays,
    departmentCode: w.departmentCode,
    checkedAt: w.checkedAt,
    sourceUrl: w.sourceUrl,
    externalId: w.externalId,
  };
  if (w.reviewState === 'auto_publish_candidate') events.push(candidate); else reviewQueue.push(candidate);
}

return [{ json: { recordKind: 'compatibilityCandidates', eventsCompat: events, reviewQueueCompat: reviewQueue, generatedAt: config.generatedAt } }];

const config = $items('Set Connector Config')[0].json;
const normalizeInputs = $items('Extract And Normalize Flood Warning Records').map((i) => i.json || {});
const sourceHealthInputs = $items('Build Source Health').map((i) => i.json || {});
const compatibilityInputs = $items('Build Compatibility Candidates').map((i) => i.json || {});
const allInputs = [...normalizeInputs, ...sourceHealthInputs, ...compatibilityInputs];

function validIso(v) { return !v || !Number.isNaN(Date.parse(v)); }
function looksLikeSecret(v) { if (typeof v !== 'string') return false; return /^[A-Za-z0-9_-]{24,}$/.test(v) && !/^https?:\/\//.test(v); }
const forbiddenPathPattern = /(^|\/)(tmp|data\/public|home\/node\/\.n8n)(\/|$)/i;

const errors = [];
const warnings = [];

if (!config.connectorId) errors.push('Missing connectorId in Set Connector Config');
if (!config.connectorNumber) errors.push('Missing connectorNumber in Set Connector Config');
if (!config.workflowName) errors.push('Missing workflowName in Set Connector Config');
if (!config.workflowVersion) errors.push('Missing workflowVersion in Set Connector Config');
if (!validIso(config.generatedAt)) errors.push('Missing or invalid generatedAt in Set Connector Config');
if (!config.outputDirectory || !config.outputDirectory.startsWith('/files/cdm-status-output')) errors.push('Forbidden or missing output directory: expected /files/cdm-status-output');
if (forbiddenPathPattern.test(config.outputDirectory || '')) errors.push('Output directory matches a forbidden path pattern');

const fullText = JSON.stringify(allInputs);
if (/bearer\s+[A-Za-z0-9_\-.]{20,}/i.test(fullText)) errors.push('Possible bearer token leaked into merged output records');
if (/apikey[\"\']?\s*[:=]\s*[\"\'][A-Za-z0-9_\-]{16,}[\"\']/i.test(fullText)) errors.push('Possible hardcoded API key value leaked into merged output records');
if (/process\.env/.test(fullText)) errors.push('process.env literal found in merged output records');
if (/\btowpath closure confirmed\b|\broute closure confirmed\b|\bdetour required\b/i.test(fullText)) errors.push('Merged output appears to claim a confirmed route/towpath closure or detour without explicit official route-impact evidence');
if (/\bcanal (closed|closure)\b/i.test(fullText) && !/no route impact indicated/i.test(fullText)) warnings.push('Canal-adjacent wording found without the mandatory no-route-impact caveat nearby; review manually');

let sawSourceHealth = false;
for (const r of allInputs) {
  if (r.recordKind === 'sourceHealth') {
    sawSourceHealth = true;
    for (const field of ['sourceId', 'sourceName', 'status', 'fetchedAt', 'staleAfterMinutes', 'httpStatus', 'recordCount', 'errors', 'warnings']) {
      if (r[field] === undefined || r[field] === null) errors.push('sourceHealth ' + (r.sourceId || 'unknown') + ' missing ' + field);
    }
    if (!validIso(r.fetchedAt)) errors.push('sourceHealth ' + r.sourceId + ' has invalid fetchedAt');
    if (!['ok', 'degraded', 'failed', 'stale', 'source_api_blocked'].includes(r.status)) errors.push('sourceHealth ' + r.sourceId + ' has invalid status enum: ' + r.status);
    continue;
  }
  if (r.recordKind === 'officialFloodWarning') {
    for (const field of ['externalId', 'sourceId', 'category', 'officialWarningLevel', 'officialWarningColor', 'routeImpactStatus', 'title', 'checkedAt', 'statusExplanation', 'statusSource']) {
      if (r[field] === undefined || r[field] === null || r[field] === '') errors.push('officialFloodWarning/' + (r.externalId || 'unknown') + ': missing required field ' + field);
    }
    if (!['rouge', 'orange', 'jaune', 'vert'].includes(r.officialWarningLevel)) errors.push('officialFloodWarning/' + r.externalId + ': invalid officialWarningLevel ' + r.officialWarningLevel);
    if (!['red', 'orange', 'yellow', 'green'].includes(r.officialWarningColor)) errors.push('officialFloodWarning/' + r.externalId + ': invalid officialWarningColor ' + r.officialWarningColor);
    if (!['not_indicated', 'reported', 'unknown'].includes(r.routeImpactStatus)) errors.push('officialFloodWarning/' + r.externalId + ': invalid routeImpactStatus ' + r.routeImpactStatus);
    if (r.routeClosureConfirmed === true || r.towpathClosureConfirmed === true || r.publicAccessClosureConfirmed === true || r.detourConfirmed === true) {
      errors.push('officialFloodWarning/' + r.externalId + ': a confirmed-impact flag is true without an explicit official route-impact source wired into this connector');
    }
    if (!validIso(r.checkedAt) || !validIso(r.startTime)) errors.push('officialFloodWarning/' + r.externalId + ': invalid ISO timestamp');
    if (!r.statusSource || r.statusSource.official !== true) errors.push('officialFloodWarning/' + r.externalId + ': elevated record missing official statusSource');
    if (r.statusExplanation) {
      const wc = r.statusExplanation.trim().split(/\s+/).length;
      if (wc < 15 || wc > 20) warnings.push('officialFloodWarning/' + r.externalId + ': statusExplanation word count ' + wc + ' outside the target 15-20 word range');
    }
    if (r.stationMappingVerified !== false && r.stationMappingVerified !== true) errors.push('officialFloodWarning/' + r.externalId + ': stationMappingVerified must be a boolean, verified:false status must not be hidden');
    if (looksLikeSecret(r.externalId) || looksLikeSecret(r.sourceUrl)) errors.push('officialFloodWarning/' + r.externalId + ': field resembles a hardcoded credential and was rejected');
    continue;
  }
  if (r.recordKind === 'compatibilityCandidates') {
    if (!Array.isArray(r.eventsCompat) || !Array.isArray(r.reviewQueueCompat)) errors.push('compatibilityCandidates missing eventsCompat[] or reviewQueueCompat[]');
  }
}
if (!sawSourceHealth) errors.push('No sourceHealth record observed in merged input (upstream fetch may not have run)');

return [{ json: { recordKind: 'validationResult', passed: errors.length === 0, errors, warnings } }, ...allInputs.map((r) => ({ json: r }))];

const config = $items('Set Connector Config')[0].json;
const items = $input.all().map((i) => i.json || {});
const validation = items.find((i) => i.recordKind === 'validationResult') || { passed: true, errors: [], warnings: [] };
const floodWarningRecords = items.filter((i) => i.recordKind === 'officialFloodWarning');
const sourceHealth = items.filter((i) => i.recordKind === 'sourceHealth');
const ignoredItems = items.filter((i) => i.recordKind === 'ignoredItem');
const compat = items.find((i) => i.recordKind === 'compatibilityCandidates') || { eventsCompat: [], reviewQueueCompat: [] };

const startedAt = sourceHealth[0]?.fetchedAt || config.generatedAt || new Date().toISOString();
const completedAt = new Date().toISOString();
const sourceUpdatedAt = sourceHealth.map((h) => h.sourceUpdatedAt).filter(Boolean).sort().slice(-1)[0] || null;
const stale = sourceHealth.some((h) => h.stale === true || h.status === 'stale');
const anyBlocked = sourceHealth.some((h) => h.status === 'source_api_blocked');
const topLevelWarnings = [...(validation.warnings || [])];
const topLevelErrors = [...(validation.errors || [])];

const manualReviewCount = floodWarningRecords.filter((w) => w.reviewState === 'manual_review_required').length;
if (manualReviewCount > 0) {
  topLevelWarnings.push(manualReviewCount + ' normalized flood warning record(s) require manual review before any route-specific operational claim.');
}
if (stale) {
  topLevelWarnings.push('Source freshness exceeded the stale threshold; output is being labeled as stale last-known-good.');
}

let status = 'SUCCESS';
if (anyBlocked || !validation.passed) {
  status = 'FAILED_NO_OUTPUT';
} else if (stale) {
  status = 'STALE_LAST_KNOWN_GOOD';
} else if (topLevelWarnings.length > 0) {
  status = 'SUCCESS_WITH_WARNINGS';
}

const connectorPayload = {
  connectorId: config.connectorId,
  connectorNumber: config.connectorNumber,
  connectorName: config.connectorName,
  workflowName: config.workflowName,
  workflowVersion: config.workflowVersion,
  generatedAt: config.generatedAt,
  timezone: config.timezone,
  status: anyBlocked ? 'source_api_blocked' : (!validation.passed ? 'failed' : stale ? 'stale' : 'ok'),
  sources: [{ sourceId: 'vigicrues', sourceName: 'Vigicrues', endpoint: config.vigicruesRssUrl, category: 'environment' }],
  officialFloodWarnings: floodWarningRecords,
  floodWarningRecords,
  routeImpactRecords: [],
  ignoredItems,
  records: floodWarningRecords,
  sourceHealth,
  attribution: { required: true, source: 'Vigicrues', official: true },
  officialWarningPolicy: { preserveOfficialLevels: true, preserveOfficialColors: true, doNotDowngradeOfficialFloodWarnings: true, separateRouteImpactFromOfficialWarning: true },
  routeImpactPolicy: { routeClosureRequiresExplicitOfficialRouteImpactSource: true, towpathClosureRequiresExplicitOfficialRouteImpactSource: true, canalNavigationStatusIsNotRouteStatus: true, defaultRouteImpactStatus: 'not_indicated' },
  routeRelevancePolicy: { routeSpecificRequiresExplicitRouteImpactEvidence: true, departmentalGeneralRequiresExplicitDepartmentWideSource: true, currentConnectorOutputDefaultScope: 'route_corridor_station_match' },
  validation: { passed: validation.passed, errors: validation.errors || [], warnings: validation.warnings || [] },
  compatibility: { targetEventsFeed: 'public/data/route-status-events.json', targetReviewQueueFeed: 'public/data/route-status-review-queue.json', targetSourceHealthFeed: 'public/data/route-status-source-health.json', mode: 'compatibility_candidate' },
};

const envelope = {
  schema_version: '1.0.0',
  connector_id: config.connectorId,
  connector_name: config.connectorName,
  run_id: config.connectorId + ':' + config.generatedAt,
  status,
  started_at: startedAt,
  completed_at: completedAt,
  generated_at: completedAt,
  source_updated_at: sourceUpdatedAt,
  record_count: floodWarningRecords.length,
  source_count: sourceHealth.length,
  sources: [config.vigicruesRssUrl],
  data: connectorPayload,
  warnings: topLevelWarnings,
  errors: topLevelErrors,
  stale,
  last_known_good: {
    is_last_known_good: stale,
    reason: stale
      ? 'Latest source update exceeded the configured freshness threshold, so this validated output is labeled stale last-known-good.'
      : 'Fresh candidate output generated for staged validation; final file is replaced only after validation passes and the staging file is atomically renamed.'
  },
  validation: {
    schema_valid: validation.passed && !anyBlocked,
  },
};

const finalPath = config.outputDirectory + '/05_flood_conditions.json';
const stagingPath = config.outputDirectory + '/05_flood_conditions.staging.json';
return [{
  json: {
    label: '05_flood_conditions',
    targetPath: stagingPath,
    finalPath,
    stagingPath,
    jsonText: JSON.stringify(envelope, null, 2) + '\n',
  }
}];

const output = [];
for (const item of $input.all()) {
  const buf = Buffer.from(item.json.jsonText, 'utf8');
  const fileName = String(item.json.targetPath).split('/').pop();
  const binary = await this.helpers.prepareBinaryData(buf, fileName, 'application/json');
  output.push({ json: item.json, binary: { data: binary } });
}
return output;

const REQUIRED_FIELDS = [
  'schema_version',
  'connector_id',
  'connector_name',
  'run_id',
  'status',
  'started_at',
  'completed_at',
  'generated_at',
  'source_updated_at',
  'record_count',
  'source_count',
  'sources',
  'data',
  'warnings',
  'errors',
  'stale',
  'last_known_good',
  'validation',
];
const ALLOWED_STATUS = new Set(['SUCCESS', 'SUCCESS_WITH_WARNINGS', 'STALE_LAST_KNOWN_GOOD', 'FAILED_NO_OUTPUT']);
const items = $input.all();
const payloadMetadata = $items('Build Flood Conditions Output Payloads').map((i) => i.json || {});
const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const meta = payloadMetadata[i] || payloadMetadata[0] || {};
  const targetPath = meta.targetPath || item.json?.targetPath || item.json?.fileName || 'unknown';
  const finalPath = meta.finalPath || item.json?.finalPath || null;
  const stagingPath = meta.stagingPath || item.json?.stagingPath || targetPath;
  if (!item.binary || !item.binary.data) {
    results.push({ json: { label: '05_flood_conditions', targetPath, finalPath, stagingPath, validJson: false, schemaValid: false, error: 'No binary data read back for ' + targetPath } });
    continue;
  }
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const text = buf.toString('utf8');
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (err) {
    results.push({ json: { label: '05_flood_conditions', targetPath, finalPath, stagingPath, validJson: false, schemaValid: false, error: 'Invalid JSON: ' + err.message } });
    continue;
  }

  const missing = REQUIRED_FIELDS.filter((field) => !(field in parsed));
  const schemaErrors = [];
  if (missing.length) schemaErrors.push('Missing top-level fields: ' + missing.join(', '));
  if (parsed.schema_version !== '1.0.0') schemaErrors.push('schema_version must equal 1.0.0');
  if (!ALLOWED_STATUS.has(parsed.status)) schemaErrors.push('status must be one of the contract enums');
  if (!Array.isArray(parsed.sources)) schemaErrors.push('sources must be an array');
  if (!Array.isArray(parsed.warnings)) schemaErrors.push('warnings must be an array');
  if (!Array.isArray(parsed.errors)) schemaErrors.push('errors must be an array');
  if (typeof parsed.stale !== 'boolean') schemaErrors.push('stale must be a boolean');
  if (!parsed.last_known_good || typeof parsed.last_known_good.is_last_known_good !== 'boolean' || typeof parsed.last_known_good.reason !== 'string') schemaErrors.push('last_known_good must include boolean is_last_known_good and string reason');
  if (!parsed.validation || parsed.validation.schema_valid !== true) schemaErrors.push('validation.schema_valid must be true before final rename');
  if (!parsed.data || parsed.data.connectorId !== parsed.connector_id) schemaErrors.push('data.connectorId must match connector_id');
  if (!String(stagingPath).endsWith('/05_flood_conditions.staging.json')) schemaErrors.push('staging path is incorrect: ' + stagingPath);
  if (!String(finalPath).endsWith('/05_flood_conditions.json')) schemaErrors.push('final path is incorrect: ' + finalPath);

  results.push({
    json: {
      label: '05_flood_conditions',
      targetPath,
      finalPath,
      stagingPath,
      validJson: true,
      schemaValid: schemaErrors.length === 0,
      recordCount: parsed.record_count,
      sourceCount: parsed.source_count,
      status: parsed.status,
      error: schemaErrors.length ? schemaErrors.join('; ') : null,
    }
  });
}
return results;

const config = $items('Set Connector Config')[0].json;
const promotionItems = $input.all().map((i) => i.json || {});
const generatedAt = config.generatedAt || new Date().toISOString();
const completedAt = new Date().toISOString();
const promotion = promotionItems[0] || {};

const normalizeItems = $items('Extract And Normalize Flood Warning Records').map((i) => i.json);
const floodWarnings = normalizeItems.filter((i) => i.recordKind === 'officialFloodWarning');
const ignoredCount = normalizeItems.filter((i) => i.recordKind === 'ignoredItem').length;
const healthItems = $items('Build Source Health').map((i) => i.json);
const sourceApiBlocked = healthItems.some((h) => h.status === 'source_api_blocked');
const sourceStale = healthItems.some((h) => h.stale === true || h.status === 'stale');

return [{
  json: {
    recordKind: 'runDiagnostics',
    ok: true,
    connectorId: config.connectorId,
    workflowName: config.workflowName,
    workflowVersion: config.workflowVersion,
    generatedAt,
    completedAt,
    validationStatus: 'passed',
    sourceStatus: sourceApiBlocked ? 'source_api_blocked' : sourceStale ? 'stale' : 'ok',
    writeStatus: 'promoted',
    infraBlocked: false,
    fileAccessRegression: false,
    sourceApiBlocked,
    outputFilenames: [promotion.finalPath].filter(Boolean),
    warningCount: floodWarnings.length,
    ignoredCount,
    routeImpactConfirmedCount: floodWarnings.filter((w) => w.routeImpactStatus === 'reported').length,
    manualReviewCount: floodWarnings.filter((w) => w.reviewState === 'manual_review_required').length,
    autoPublishCandidateCount: floodWarnings.filter((w) => w.reviewState === 'auto_publish_candidate').length,
    errors: [],
    warnings: sourceStale ? ['Source freshness exceeded threshold; payload still validated and was marked stale.'] : [],
    nextAction: 'Workflow output validated and atomically promoted to the production path.',
    folderMoveRequired: false,
  },
}];

const results = $input.all().map((i) => i.json || {});
const failures = results.filter((r) => r.validJson !== true || r.schemaValid !== true || r.error);
if (failures.length) {
  throw new Error('Staged output validation failed: ' + failures.map((f) => f.error || f.targetPath || 'unknown').join(' | '));
}
const result = results[0] || {};
if (!result.stagingPath || !result.finalPath) {
  throw new Error('Missing stagingPath or finalPath for atomic rename');
}
return [{ json: {
  ...result,
  command: 'mv "' + result.stagingPath + '" "' + result.finalPath + '"'
} }];
